argv:
set -u; S=$PWD/skills/confidence-protocol/scripts/confidence.py; T=$(python3 -c 'import tempfile;print(tempfile.mkdtemp())'); cd $T; git init -q r && cd r && git -c user.email=a@b -c user.name=a commit -q --allow-empty -m i; echo tracked > f.txt; git add f.txt; git -c user.email=a@b -c user.name=a commit -q -m f;
echo '--- json failure binary'; python3 -B $S run --json --id b --directory .confidence -- python3 -c 'import sys;sys.stdout.buffer.write(bytes(range(256)));sys.exit(7)' > out.bin; echo rc=$?; cat out.bin; echo; python3 -c 'import json,hashlib;r=json.load(open(".confidence/runs/b.json"));d=open(".confidence/runs/b.log","rb").read();print(r["exit_code"],r["workspace_binding"],d==bytes(range(256)),hashlib.sha256(d).hexdigest()==r["log_sha256"])';
echo '--- json mutation'; python3 -B $S run --json --id m --directory .confidence -- python3 -c 'open("f.txt","a").write("x")'; echo rc=$?;
echo '--- json untracked creation'; python3 -B $S run --json --id u --directory .confidence -- python3 -c 'open("new.py","w").write("x")'; echo rc=$?;
echo '--- json no-op'; python3 -B $S run --json --id n --directory .confidence -- python3 -c 'print(1)'; echo rc=$?;
echo '--- default replay'; python3 -B $S run --id d --directory .confidence -- python3 -c 'print("hello")'; echo rc=$?;
echo '--- non-git'; mkdir -p $T/ng; python3 -B $S run --json --id g --directory $T/ng/.c --cwd $T/ng -- python3 -c 'pass'; echo rc=$?; rm -rf $T
